import java.io.*;
import java.math.BigInteger;
import java.util.*;

public class Main {
    static long MOD = 998244353;
    static long[] factorials;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));
        int testCases = 1;
        while (testCases-- > 0) {
            int n = scanner.nextInt();
            long kLong = scanner.nextLong();
            factorials = new long[n + 1];
            factorials[0] = 1L;
            for (int i = 1; i <= n; i++) {
                factorials[i] = (factorials[i - 1] * i) % MOD;
            }
            if (kLong == 0) {
                writer.println(factorials[n]);
            } else if (kLong >= n) {
                writer.println(0);
            } else {
                int k = (int) kLong;
                long total = 0L;
                long sign = 1L;
                int l = n - k;
                for (int i = 0; i <= l; i++) {
                    long term = (quickPower(l - i, n) * combination(l, l - i)) % MOD;
                    if (sign == -1L) {
                        total = (total - term + MOD) % MOD;
                    } else {
                        total = (total + term) % MOD;
                    }
                    sign *= -1L;
                }
                long result = (2L * combination(n, k) * total) % MOD;
                writer.println(result);
            }
        }
        writer.close();
        scanner.close();
    }

    public static long combination(int n, int m) {
        if (m == 0 || m == n) return 1L;
        if (m > n || m < 0) return 0L;
        long numerator = factorials[n];
        long denominator = (factorials[m] * factorials[n - m]) % MOD;
        long invDenominator = quickPower(denominator, MOD - 2);
        return (numerator * invDenominator) % MOD;
    }

    public static long quickPower(long base, long exp) {
        long result = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }
}
